                {
                    "productId": pid,
                    "name": product.get("name"),
                    "maxQuantity": available_qty,
                    "price": item.get("price"),
                    "image": product.get("images", [None])[0] if product.get("images") else None,
                    "sellerId": product.get("sellerId"),
                }
            )

    if not seller_id:
        seller_id = order.get("sellerId")

    # Check seller's delivery slot settings
    seller_allows_slots = False
    if seller_id:
        seller_user = await user_repository.findById(seller_id)
        if seller_user:
            seller_perms = seller_user.get("sellerPermissions") or {}
            seller_allows_slots = bool(seller_perms.get("allowDeliverySlots", False))

    # Calculate return delivery charge for customer's pincode
