            "items": [i.dict() for i in request_data.items],
            "paymentMethod": request_data.paymentMethod,
            "upiPaymentScreenshot": screenshot_path,
            "notes": request_data.notes,
            "sellerId": seller_id,
            "deliverySlotId": request_data.deliverySlotId if eligibility.get("sellerAllowsDeliverySlots") else None,
            "deliverySlotConfigId": request_data.deliverySlotConfigId if eligibility.get("sellerAllowsDeliverySlots") else None,
            "deliverySlotDate": request_data.deliverySlotDate if eligibility.get("sellerAllowsDeliverySlots") else None,
            "status": ReturnRequestStatus.PENDING.value,
            "deliveryCharge": eligibility.get("returnDeliveryCharge", 0),
