                "link": f"/valet",
                "data": {
                    "returnId": request_id,
                    "type": "valet_return_assignment",
                    "timeoutMinutes": 20,
                },
            },
        )
    except Exception as push_err:
        logger.warning("[AssignValetReturn] Push notification failed: %s", push_err)

    return await populate_return_request(updated)


