@router.put("/{request_id}/valet-response", response_model=ReturnRequestResponse)
async def valet_return_response(
    request_id: str,
    response_data: ValetReturnResponseRequest,
    current_user: dict = Depends(require_super_admin_or_valet),
):
    """
    Valet accepts or declines an assigned return pickup request within 20 minutes.
    - Accept: moves status to 'assigned' (valetId set, pendingValetId cleared).
    - Decline: auto-cascades to next eligible valet (or reverts to 'pending').
    """
    if response_data.action not in ("accept", "decline"):
        raise HTTPException(status_code=400, detail="action must be 'accept' or 'decline'")

    req = await return_request_repository.findById(request_id)
    if not req:
        raise HTTPException(status_code=404, detail="Return request not found")

    if req.get("status") != ReturnRequestStatus.PENDING_VALET.value:
        raise HTTPException(status_code=400, detail="Return request is not awaiting valet confirmation")

    if current_user.get("role") == "valet":
        if str(req.get("pendingValetId", "")) != str(current_user["_id"]):
            raise HTTPException(status_code=403, detail="This return pickup is not assigned to you")

    assigned_at_str = req.get("valetAssignedAt", "")
    if assigned_at_str:
        try:
            assigned_at = datetime.fromisoformat(assigned_at_str.replace("Z", "+00:00")).replace(tzinfo=None)
            if datetime.utcnow() >= assigned_at + timedelta(minutes=20):
                raise HTTPException(
                    status_code=400,
                    detail="The 20-minute acceptance window for this return pickup has expired",
                )
        except HTTPException:
            raise
        except Exception:
            pass

    now_iso = datetime.utcnow().isoformat() + "Z"
    valet_id = str(current_user["_id"]) if current_user.get("role") == "valet" else str(req.get("pendingValetId", ""))

    # ── ACCEPT ────────────────────────────────────────────────────────────────
    if response_data.action == "accept":
        updated = await return_request_repository.update(
            request_id,
            {
                "status": ReturnRequestStatus.ASSIGNED.value,
                "valetId": valet_id,
                "pendingValetId": None,
                "valetAcceptedAt": now_iso,
            },
        )

        try:
            from app.services.push_notification_service import push_notification_service
            super_admin = await user_repository.findOne({"role": "super_admin"})
            valet_user = await user_repository.findById(valet_id)
            valet_name = valet_user.get("name", "The valet") if valet_user else "The valet"
            return_num = req.get("returnId", request_id)
            if super_admin:
                await push_notification_service.send_to_user(
                    str(super_admin["_id"]),
                    {
                        "title": "Return Pickup Accepted",
                        "message": f"{valet_name} accepted return pickup #{return_num}.",
                        "link": "/admin/returns-management",
                        "data": {"returnId": request_id, "type": "valet_return_accepted"},
                    },
                )
        except Exception as e:
            logger.warning("[ValetReturnResponse] Push notification failed: %s", e)

        return await populate_return_request(updated)

    # ── DECLINE ───────────────────────────────────────────────────────────────
    decline_history = list(req.get("valetDeclineHistory") or [])
    if valet_id and valet_id not in decline_history:
        decline_history.append(valet_id)

    await return_request_repository.update(
        request_id,
        {
            "valetDeclinedAt": now_iso,
            "valetDeclineReason": response_data.declineReason or "",
            "valetDeclineHistory": decline_history,
            "pendingValetId": None,
            "valetCascadeCount": (req.get("valetCascadeCount") or 0) + 1,
        },
    )

    from app.jobs.valet_timeout_job import _cascade_or_revert_return

    req_fresh = await return_request_repository.findById(request_id)
    await _cascade_or_revert_return(req_fresh)

    updated_final = await return_request_repository.findById(request_id)
    return await populate_return_request(updated_final)


@router.put("/valet/{request_id}/collect", response_model=ReturnRequestResponse)
async def valet_collect(request_id: str, current_user: dict = Depends(require_super_admin_or_valet)):
    """Valet marks return as collected"""
    req = await return_request_repository.findById(request_id)
    if not req:
        raise HTTPException(status_code=404, detail="Return request not found")

    if current_user.get("role") == "valet" and str(req.get("valetId")) != str(current_user.get("_id")):
        raise HTTPException(status_code=403, detail="Return request not assigned to you")

    if req.get("status") != ReturnRequestStatus.ASSIGNED.value:
        raise HTTPException(status_code=400, detail="Return request is not in ASSIGNED state")

    updated = await return_request_repository.update(request_id, {"status": ReturnRequestStatus.COLLECTED.value})

    return await populate_return_request(updated)


@router.put("/admin/{request_id}/complete", response_model=ReturnRequestResponse)
async def complete_return(
    request_id: str, background_tasks: BackgroundTasks, current_user: dict = Depends(require_super_admin)
):
    """Super Admin completes returns (marks as RETURNED) and handles stock update"""
    req = await return_request_repository.findById(request_id)
    if not req:
        raise HTTPException(status_code=404, detail="Return request not found")

    if req.get("status") not in [ReturnRequestStatus.COLLECTED.value, ReturnRequestStatus.ASSIGNED.value]:
        raise HTTPException(status_code=400, detail="Return request must be collected first")

    updated = await return_request_repository.update(request_id, {"status": ReturnRequestStatus.RETURNED.value})

    # Restock items
    for item in req.get("items", []):
        try:
            product = await product_repository.findById(item.get("productId"))
            if product:
                await product_repository.update(
                    product.get("_id"), {"stock": product.get("stock", 0) + item.get("quantity", 0)}
                )
        except (ValueError, KeyError, TypeError) as e:
            logger.warning("Data error restocking product %s for return %s: %s", item.get("productId"), req.get("_id"), str(e))
        except Exception as e:
            logger.error("Unexpected error restocking product %s for return %s: %s", item.get("productId"), req.get("_id"), str(e), exc_info=True)

    populated_req = await populate_return_request(updated)
    email = populated_req.get("user", {}).get("email") if populated_req.get("user") else None
    if email:
        background_tasks.add_task(email_service.send_order_returned_email, email, populated_req)

    return populated_req


@router.put("/admin/{request_id}/reject", response_model=ReturnRequestResponse)
async def reject_return(
    request_id: str, update_data: ReturnRequestUpdate, current_user: dict = Depends(require_super_admin)
):
    """Super Admin rejects the return request"""
    req = await return_request_repository.findById(request_id)
    if not req:
        raise HTTPException(status_code=404, detail="Return request not found")

    updated = await return_request_repository.update(
        request_id, {"status": ReturnRequestStatus.REJECTED.value, "notes": update_data.notes or req.get("notes")}
    )

    return await populate_return_request(updated)

