{/* ── Pending Assignment Cards ── */}
{pendingAssignments.length > 0 && (
  <div style={{ background: '#fffbeb', borderBottom: '2px solid #fcd34d', padding: '12px 16px' }}>
    <h3 style={{ margin: '0 0 10px', fontSize: 15, fontWeight: 700, color: '#92400e' }}>
      ⚡ New Delivery Request{pendingAssignments.length > 1 ? 's' : ''}
    </h3>
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      {pendingAssignments.map((o) => {
        const secs = countdown[o._id] ?? 0;
        const mins = Math.floor(secs / 60);
        const secsLeft = secs % 60;
        const isUrgent = (o as any).isUrgentDelivery;
        const isExpiring = secs < 60;
        const isResponding = respondingOrderId === o._id;
        const showDecline = showDeclineInput === o._id;
        return (
          <div key={o._id} style={{
            background: '#fff', borderRadius: 12, padding: '14px 16px',
            border: `2px solid ${isExpiring ? '#fca5a5' : '#fcd34d'}`,
            boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 10 }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 15 }}>
                  Order #{o.orderNumber || o._id.slice(-6)}
                  {isUrgent && <span style={{ marginLeft: 6, color: '#dc2626', fontSize: 12 }}>⚡ Urgent</span>}
                </div>
                <div style={{ fontSize: 13, color: '#6b7280', marginTop: 3 }}>
                  ₹{o.total.toFixed(2)} · {o.paymentMethod?.toUpperCase()}
                </div>
              </div>
              <div style={{
                fontWeight: 700, fontSize: 20,
                color: isExpiring ? '#dc2626' : '#92400e',
              }}>
                {mins}:{String(secsLeft).padStart(2, '0')}
              </div>
            </div>
            {showDecline ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <input
                  placeholder="Reason for declining (optional)"
                  value={declineReason}
                  onChange={(e) => setDeclineReason(e.target.value)}
                  style={{
                    padding: '8px 12px', borderRadius: 8, border: '1px solid #d1d5db',
                    fontSize: 13, width: '100%',
                  }}
                />
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    onClick={() => handleValetResponse(o._id, 'decline')}
                    disabled={isResponding}
                    style={{
                      flex: 1, padding: '9px', borderRadius: 8, border: 'none',
                      background: '#dc2626', color: '#fff', fontWeight: 700, fontSize: 13,
                      cursor: isResponding ? 'not-allowed' : 'pointer',
                    }}
                  >
                    {isResponding ? '…' : 'Confirm Decline'}
                  </button>
                  <button
                    onClick={() => { setShowDeclineInput(null); setDeclineReason(''); }}
                    style={{
                      padding: '9px 14px', borderRadius: 8, border: '1px solid #d1d5db',
                      background: '#fff', color: '#374151', fontWeight: 600, fontSize: 13, cursor: 'pointer',
                    }}
                  >
                    Back
                  </button>
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', gap: 8 }}>
                <button
